import{_ as e,o as r,c as a,ag as o}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"Graduate Work (CS [5xxx])","description":"","frontmatter":{"source":"graduate/README.md"},"headers":[],"relativePath":"graduate/index.md","filePath":"graduate/index.md"}'),s={name:"graduate/index.md"};function n(d,t,i,h,l,u){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="graduate-work-cs-5xxx" tabindex="-1">Graduate Work (CS [5xxx]) <a class="header-anchor" href="#graduate-work-cs-5xxx" aria-label="Permalink to &quot;Graduate Work (CS [5xxx])&quot;">​</a></h1><blockquote><p>CS [5xxx] students take the same course as CS [4xxx] students, and add the work of a researcher in the field: presenting and questioning a paper, critiquing one in writing, and running a small empirical study of their own.</p></blockquote><h2 id="what-is-different-for-cs-5xxx" tabindex="-1">What is different for CS [5xxx] <a class="header-anchor" href="#what-is-different-for-cs-5xxx" aria-label="Permalink to &quot;What is different for CS [5xxx]&quot;">​</a></h2><p>The catalog entry states it in the University of Idaho&#39;s usual words for joint-listed CS courses: <strong>&quot;Additional projects/assignments required for graduate credit.&quot;</strong> The same sentence appears in, for example, CS 4200/5200, 4211/5211 and 4441/5441 (<a href="https://catalog.uidaho.edu/courses/cs/" target="_blank" rel="noreferrer">UIdaho CS courses</a>).</p><ul><li><strong>The same:</strong> every Seminar and Lab, every lab and assignment, the due-date quizzes, both oral exams, the team project and the final defense. You may be on a mixed team with CS [4xxx] students, with exactly the same team expectations.</li><li><strong>Added:</strong> a paper presentation and a discussant role, a critique, and an empirical study, about <strong>1.5 hours a week</strong> on top of the CS [4xxx] workload (about 7.5 hours a week outside class instead of 6).</li><li><strong>Weighted differently:</strong> the shared components count for less, so that the graduate work is 20% of your grade (<a href="#weights">weights</a>).</li><li><strong>Registration:</strong> 5000-level courses are restricted to students in the College of Graduate Studies, except that a senior with 90 or more credits and a 3.00 GPA may enroll with the required approvals (catalog Course Information; Regulation B-6). Under catalog Regulation B-11, a student &quot;may only earn credit at the level the student initially completes the course&quot; (<a href="https://catalog.uidaho.edu/general-requirements-academic-procedures/b-registration/" target="_blank" rel="noreferrer">catalog, B-Registration</a>), so choose your level before the term.</li></ul><h2 id="requirements-at-a-glance" tabindex="-1">Requirements at a glance <a class="header-anchor" href="#requirements-at-a-glance" aria-label="Permalink to &quot;Requirements at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>What you do</th><th>When</th><th>Weight</th><th>Details</th></tr></thead><tbody><tr><td><strong>Paper presentation</strong></td><td>A 20-minute presentation of a paper from the graduate seminar list, leading the discussion</td><td>One Seminar, weeks 3–14</td><td>4.5%</td><td><a href="./paper-presentations.html">Paper Presentations</a></td></tr><tr><td><strong>Discussant</strong></td><td>Three prepared questions for a classmate&#39;s presentation; open the discussion</td><td>One Seminar, weeks 3–14</td><td>1.5%</td><td><a href="./paper-presentations.html#the-discussant">Paper Presentations: The discussant</a></td></tr><tr><td><strong>Critique</strong></td><td>1,000 words on one paper, or a tool experience report, on Canvas</td><td>Before the week 13 Seminar</td><td>3%</td><td><a href="#the-critique">below</a></td></tr><tr><td><strong>Empirical study</strong></td><td>A small replication or extension at $0, alone or in a pair: protocol, interim results, draft, talk, paper</td><td>Weeks 3–16</td><td>11%</td><td><a href="./empirical-study.html">The Empirical Study</a></td></tr></tbody></table><p>The study&#39;s 11% splits as protocol 1.5% · interim results 1.5% · talk 2% · paper 6%.</p><h2 id="weights" tabindex="-1">Weights <a class="header-anchor" href="#weights" aria-label="Permalink to &quot;Weights&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>CS [4xxx]</th><th>CS [5xxx]</th></tr></thead><tbody><tr><td>Labs and assignments</td><td>35%</td><td>30%</td></tr><tr><td>Due-date quizzes</td><td>10%</td><td>5%</td></tr><tr><td>Team project</td><td>30%</td><td>25%</td></tr><tr><td>Oral exams</td><td>15%</td><td>15%</td></tr><tr><td>Reading responses and Seminar participation</td><td>10%</td><td>5%</td></tr><tr><td>Graduate work</td><td>—</td><td>20%</td></tr></tbody></table><p>The full grading rules are in the <a href="./../assessment/">assessment guide</a>; everything there applies to you, including the C-or-higher condition (both oral exams and the final defense).</p><h2 id="learning-outcomes" tabindex="-1">Learning outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to &quot;Learning outcomes&quot;">​</a></h2><p>In addition to the course&#39;s <a href="./../SYLLABUS.html#3-learning-outcomes">learning outcomes</a>, CS [5xxx] students will be able to:</p><ul><li><strong>Analyze and present</strong> research in AI for software engineering: say what a paper shows, how strong the evidence is, and what it means for practice, and lead a discussion of it. <em>Assessed by</em> the presentation, the discussant role and the critique.</li><li><strong>Design and run</strong> a small empirical study and report it in a short paper. <em>Assessed by</em> the study&#39;s protocol, interim results, talk and paper.</li></ul><h2 id="workload" tabindex="-1">Workload <a class="header-anchor" href="#workload" aria-label="Permalink to &quot;Workload&quot;">​</a></h2><p>Planning estimates, about 24–28 hours over the semester:</p><table tabindex="0"><thead><tr><th>Task</th><th>Hours</th></tr></thead><tbody><tr><td>Presentation: read the paper twice, prepare the talk and the value-added part, rehearse</td><td>6–7</td></tr><tr><td>Discussant: read the paper, write three questions and a short note</td><td>2</td></tr><tr><td>Critique or tool experience report</td><td>3–4</td></tr><tr><td>Empirical study: protocol (2), running it (5–6), interim report (1), draft and paper (4–5), talk (1.5)</td><td>13–15</td></tr></tbody></table><p>The study is deliberately small: the replicable studies on the course&#39;s list were chosen because they can be done in about four weeks of part-time work at $0 (<a href="./empirical-study.html#choosing-a-study">The Empirical Study: Choosing a study</a>). Plan your runs early: the lab machine is one shared queue.</p><h2 id="schedule" tabindex="-1">Schedule <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;Schedule&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>Graduate work</th></tr></thead><tbody><tr><td>1</td><td>Rank three papers for your presentation on Canvas; read the replicable-studies list</td></tr><tr><td>2</td><td>The presentation and discussant schedule is posted</td></tr><tr><td>3–14</td><td>Presentations, one per Seminar; you present once and are discussant once</td></tr><tr><td>3–5</td><td>Choose your study; talk to the instructor about any proposal of your own</td></tr><tr><td>6</td><td><strong>Study protocol</strong> due before the week 7 Seminar</td></tr><tr><td>11</td><td><strong>Interim results</strong> due before the week 12 Seminar</td></tr><tr><td>12</td><td><strong>Critique</strong> due before the week 13 Seminar</td></tr><tr><td>14</td><td><strong>Paper draft</strong> due before the week 15 Seminar</td></tr><tr><td>15</td><td><strong>Study talks</strong> in the Seminar (a presentation is not an exam, so Regulation H-1-a allows it)</td></tr><tr><td>16</td><td><strong>Final paper</strong> due by 11:59 pm on the last day of finals week</td></tr></tbody></table><p>Grace tokens apply to the protocol, interim results, critique, draft and final paper, but not to the presentation, the discussant role or the talk, and never past the University&#39;s grade deadline.</p><h2 id="the-critique" tabindex="-1">The critique <a class="header-anchor" href="#the-critique" aria-label="Permalink to &quot;The critique&quot;">​</a></h2><p><strong>3% · 30 points · on Canvas · 🔴 AI off · due before the week 13 Seminar.</strong> About 1,000 words. Choose one of two forms.</p><p><strong>A paper critique</strong> of one paper from the <a href="./paper-presentations.html#the-papers">graduate seminar list</a> (not the one you present) or another paper the instructor approves. Use CU Boulder&#39;s six headings (<a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperCritiques.html" target="_blank" rel="noreferrer">CU Boulder</a>): <strong>Summary</strong> · <strong>What I liked</strong> · <strong>What I disliked</strong> · <strong>Future directions</strong> · <strong>Open questions</strong> · <strong>Most important for class discussion</strong>.</p><p><strong>A tool experience report</strong>, CU Boulder&#39;s alternative: read a paper that comes with a tool, run the tool on a use case of your own, and report your experience, its strengths and weaknesses, its potential for practical impact, and a reflection that includes &quot;one improvement&quot; for the tool&#39;s creators. The tool must run at $0 on public code, under the data rule. For example, the agentic property-based testing prompt and code from Maaz et al. are public (<a href="https://github.com/mmaaz-git/agentic-pbt" target="_blank" rel="noreferrer">agentic-pbt</a>) and could be pointed at the class codebase or <code>roomly</code>.</p><table tabindex="0"><thead><tr><th>Criterion</th><th>Exemplary</th><th>Proficient</th><th>Developing</th><th>Missing</th></tr></thead><tbody><tr><td><strong>Accurate summary</strong> (or, for a tool report, an accurate account of what the tool does and how you ran it)</td><td><strong>5</strong> · The question, method and main result, with numbers, in your own words</td><td><strong>4</strong> · Accurate, with one gap</td><td><strong>2</strong> · Misses or misstates the main result</td><td><strong>0</strong> · Missing</td></tr><tr><td><strong>Strengths and weaknesses</strong></td><td><strong>8</strong> · Specific, with evidence from the paper (a table, a design choice) or your own run; separates what the paper shows from what it claims</td><td><strong>6</strong> · Specific strengths and weaknesses</td><td><strong>3</strong> · Generic (&quot;the sample is small&quot;)</td><td><strong>0</strong> · Missing</td></tr><tr><td><strong>Validity and generalization</strong></td><td><strong>8</strong> · At least two threats to validity (construct, internal, external), and whether the result would hold for the class codebase or your team&#39;s workflow</td><td><strong>6</strong> · One threat analyzed</td><td><strong>3</strong> · Named without analysis</td><td><strong>0</strong> · Missing</td></tr><tr><td><strong>Future directions and open questions</strong></td><td><strong>6</strong> · A follow-up study someone could actually run, with what it would measure; questions the paper leaves open</td><td><strong>4</strong> · Plausible directions</td><td><strong>2</strong> · Vague</td><td><strong>0</strong> · Missing</td></tr><tr><td><strong>Clarity</strong></td><td><strong>3</strong> · Clear, organized under the headings, about 1,000 words, sources cited</td><td><strong>2</strong> · Mostly clear</td><td><strong>1</strong> · Hard to follow, or far off the length</td><td><strong>0</strong> · —</td></tr></tbody></table><h2 id="ai-use-for-graduate-work" tabindex="-1">AI use for graduate work <a class="header-anchor" href="#ai-use-for-graduate-work" aria-label="Permalink to &quot;AI use for graduate work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Label</th><th>Graduate work</th></tr></thead><tbody><tr><td>🟢 <strong>AI on</strong></td><td>Preparing slides and figures for your presentation (say so on the last slide); help understanding a paper&#39;s background; analysis code for your study (disclosed in the paper and its <code>AI_LOG.md</code>)</td></tr><tr><td>🟡 <strong>AI limited</strong></td><td>The empirical study as a whole: code may be AI-assisted and is disclosed; the research question, the design and the prose of the protocol, interim report and paper are yours</td></tr><tr><td>🔴 <strong>AI off</strong></td><td>The critique or tool experience report; your discussant questions and note; the prose of your study&#39;s documents; answering questions live in your presentation and talk</td></tr></tbody></table><p>The complete course list is in <a href="./../SYLLABUS.html#8-ai-use-policy">section 8 of the syllabus</a>.</p><h2 id="why-these-requirements" tabindex="-1">Why these requirements <a class="header-anchor" href="#why-these-requirements" aria-label="Permalink to &quot;Why these requirements&quot;">​</a></h2><p>UIdaho precedent and peer courses support a graduate component worth roughly 15–25% of the grade (<a href="./../research/notes/courses-upper-division.html">course notes</a>). ANU&#39;s COMP8020 adds a short critical research note of about 1,000 words to the undergraduate project (<a href="https://programsandcourses.anu.edu.au/2026/course/COMP8020/Second%20Semester/9057" target="_blank" rel="noreferrer">ANU</a>); CMU&#39;s 17-745 replaces homework with a research project (<a href="https://mlip-cmu.github.io/f2025" target="_blank" rel="noreferrer">MLiP</a>); CU Boulder&#39;s and Cornell&#39;s graduate seminars run on student presentations, discussants and critiques (<a href="https://danny.cs.colorado.edu/courses/csci7000-005_Sp26/paperPresentation.html" target="_blank" rel="noreferrer">CU Boulder</a>; <a href="https://www.cs.cornell.edu/courses/cs6158/2026fa/" target="_blank" rel="noreferrer">Cornell CS 6158</a>). This course adds the graduate work on top of the shared course, as ANU does, and keeps the study small enough to finish well. The presentations also give the undergraduates a weekly window into the research, at the cost of one posted question each.</p>',31)])])}const g=e(s,[["render",n]]);export{p as __pageData,g as default};
